DECLARE
    V_DOCUMENT_ID RAW(16);
    V_REQUEST_ID  RAW(16);
BEGIN

    V_DOCUMENT_ID :=
        HEXTORAW(
            REPLACE(
                '{{ appsmith.store.MMS_DOCUMENT_DELETE_ID }}',
                '-',
                ''
            )
        );

    V_REQUEST_ID :=
        HEXTORAW(
            REPLACE(
                '{{ appsmith.store.MMS_DOCUMENT_DELETE_REQUEST_ID }}',
                '-',
                ''
            )
        );

    TALY_BO_REP.MMS_DOCUMENT_PKG.DELETE_DOCUMENT(
        P_DOCUMENT_ID => V_DOCUMENT_ID,
        P_REQUEST_ID  => V_REQUEST_ID
    );

END;
